contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, bool useRejectingRecipient) public payable {
        // Ensure this contract has enough Ether to fund the withdrawal if it succeeds.
        require(address(this).balance >= 1 ether);
        if (useRejectingRecipient) {
            recipient = address(new RejectingRecipient());
        } else {
            recipient = address(new AcceptingRecipient());
        }

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool canReceive = !useRejectingRecipient;
        assert(reverted == !canReceive);
    }
}

contract RejectingRecipient {
    receive() external payable {
        revert();
    }
}

contract AcceptingRecipient {
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(address(this).balance >= 100);

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The call either completes or reverts; a completed call must have
        // moved exactly 100 wei to the recipient, and a reverted call must
        // have transferred nothing (value is conserved).
        uint balBefore = address(this).balance;
        // Note: balBefore is read after the call for conservation check:
        // if success, this contract sent 100; if revert, nothing was sent.
        // We check that the recipient contract's balance reflects only a
        // successful transfer of 100 wei.
        bool sent = !reverted;
        assert(sent ? (address(this).balance == balBefore) : (address(this).balance == balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(recipient != address(0), "zero recipient");
        require(recipient != address(c), "recipient is c");

        // Seed the recipient's reward and drive c through the public entry
        // that credits the reward and then attempts a withdrawal.
        c.getFirstWithdrawalBonus(recipient);

        uint balBefore = address(c).balance;
        (bool success, ) = recipient.call{value: 0}("");

        // If the low-level probe to the recipient succeeded, then the
        // recipient can receive Ether and the withdrawal from c must have
        // succeeded when getFirstWithdrawalBonus was called, so c's balance
        // should have decreased by 100 from the fresh deployment.
        // If the probe reverted, the recipient rejects Ether, so the withdrawal
        // inside c must have reverted and rolled back, leaving c's balance as it was.
        assert(success ? address(c).balance == balBefore - 100 : address(c).balance == balBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(recipient != address(0), "zero recipient");
        require(recipient != address(c), "recipient is c");

        c.getFirstWithdrawalBonus(recipient);

        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (bool probeOk, ) = recipient.call{value: 0}("");

        assert(probeOk == reverted && (reverted ? address(c).balance == balanceBefore : true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(recipient != address(0), "zero recipient");
        require(address(this).balance >= amount, "not enough balance");

        // Seed c with the exact amount to be paid out in the deciding call.
        c.getFirstWithdrawalBonus{value: amount}(recipient);

        // Read before-values through c's public/observable surface only.
        uint cBalanceBefore = address(c).balance;
        uint rewardBefore = c.rewardsForA(recipient);

        // Deciding call: direct, top-level, through withdrawReward.
        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalanceAfter = address(c).balance;
        uint rewardAfter = c.rewardsForA(recipient);

        assert(
            reverted
                ? (cBalanceAfter == cBalanceBefore && rewardAfter == rewardBefore)
                : (cBalanceAfter + rewardBefore == cBalanceBefore && rewardAfter == 0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        // The recipient must be a valid address for a transfer attempt.
        require(recipient != address(0), "zero recipient");

        // Try to establish a nonzero reward for the recipient by claiming the bonus.
        // If the recipient rejects Ether, this call reverts; in that case there is no
        // reward to withdraw, so we skip the deciding call and assert the trivial
        // postcondition that no reward was created and c's balance is unchanged.
        try c.getFirstWithdrawalBonus(recipient) {
            uint cBalanceBefore = address(c).balance;
            uint rewardBefore = c.getFirstWithdrawalBonus.selector == 0 ? 0 : 0; // placeholder, not used
        } catch {
            assert(address(c).balance == 0);
            return;
        }

        uint cBalanceBefore = address(c).balance;

        // The deciding call: a direct, top-level call to withdrawReward.
        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalanceAfter = address(c).balance;

        assert(
            reverted
                ? (cBalanceAfter == cBalanceBefore)
                : (cBalanceAfter + 100 == cBalanceBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(recipient != address(0), "zero recipient");
        require(recipient != address(c), "recipient cannot be the contract itself");

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the recipient rejects Ether, the call must revert because the transfer fails.
        assert(!reverted || recipient.balance == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(0));
        require(recipient != address(this));

        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        if (!firstReverted) {
            bool secondReverted;
            try c.getFirstWithdrawalBonus(recipient) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            assert(secondReverted);
        } else {
