contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        // Setup: credit the recipient with a 100-wei reward via the bonus path.
        // This may revert if the recipient rejects Ether, but rewardsForA is set first.
        // Use a try/catch only to tolerate that revert; the direct withdrawReward call
        // below is the deciding call.
        try c.getFirstWithdrawalBonus(recipient) { } catch { }

        // Deciding call: a direct withdrawReward on the recipient.
        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }

        // The rule: regardless of whether the direct call reverted or succeeded,
        // the recipient's reward is zero afterward.
        // There is no public getter for rewardsForA, so observe the same effect through
        // a second direct withdrawReward: if any reward remained it would either
        // transfer again or revert, but no reward getter is exposed.
        // To express "reward is zero" over the public surface, note that calling
        // withdrawReward again on the same recipient must succeed when the recipient
        // accepts Ether (true for this test contract) and must not revert.
        bool reverted2;
        try c.withdrawReward(recipient) { reverted2 = false; } catch { reverted2 = true; }

        assert(!(reverted == false && reverted2 == true));
    }

    receive() external payable { }
}

